using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

/// <summary>
/// Procedural lightning bolt (like the reference: white-hot core, blue glow, jagged branches, impact sparks).
///
///   bolt.Strike(startPosition, endPosition);     // fire it
///
/// How it works (mobile friendly):
///  - ONE mesh holds the main bolt + all branches (1 draw call, ~300 vertices).
///  - The path is generated by midpoint displacement and re-rolled ~22x per second while alive, which gives the
///    typical lightning flicker. The shader makes the ribbon face the camera.
///  - The strike is "drawn" from start to end in a few hundredths of a second, holds, then fades out.
///  - An additive glow quad + a few spark particles play at the impact point.
/// </summary>
[DisallowMultipleComponent]
public class LightningBolt : MonoBehaviour
{
    [Header("References (auto-filled by the builder)")]
    public MeshFilter boltMeshFilter;
    public MeshRenderer boltRenderer;
    public Renderer impactGlow;
    public ParticleSystem sparks;

    [Header("Size")]
    [Tooltip("Overall size: scales the ribbon width, the impact glow and the sparks together. The bolt LENGTH always comes from Strike(start, end).")]
    [Min(0.05f)] public float size = 1f;
    [Tooltip("Extra multiplier for the spark particles only")]
    [Min(0.05f)] public float sparkSize = 1f;

    [Header("Shape")]
    [Tooltip("Subdivisions: segments = 2^detail. 5 = 32 segments")]
    [Range(2, 6)] public int detail = 5;
    [Tooltip("How far the path zig-zags (fraction of the bolt length)")]
    [Range(0.02f, 0.5f)] public float jaggedness = 0.2f;
    [Tooltip("Base ribbon width in world units (multiplied by Size)")]
    public float width = 0.3f;

    [Header("Branches")]
    [Range(0, 8)] public int branchCount = 3;
    [Tooltip("Angle away from the main bolt (degrees)")]
    public Vector2 branchAngle = new Vector2(20f, 55f);
    [Tooltip("Branch length as a fraction of the main bolt length")]
    public Vector2 branchLength = new Vector2(0.15f, 0.35f);
    [Range(0.1f, 1f)] public float branchWidth = 0.55f;
    [Range(0.1f, 1f)] public float branchIntensity = 0.7f;

    [Header("Timing")]
    public float lifetime = 0.35f;
    [Tooltip("Seconds for the bolt to travel from start to end")]
    public float revealTime = 0.05f;
    [Tooltip("How often the shape is re-rolled (flicker)")]
    public float regenerateRate = 22f;
    [Range(0f, 1f)] public float flickerAmount = 0.35f;
    [Range(0f, 1f)] public float dropoutChance = 0.08f;

    [Header("Impact")]
    [Tooltip("Base impact glow diameter (multiplied by Size)")]
    public float impactGlowSize = 2.2f;

    [Header("Preview / Auto-fire (turn off for gameplay)")]
    [Tooltip("Keeps striking forward so you can see it. Disable and call Strike() from your spell code.")]
    public bool previewLoop = true;
    public float previewLength = 8f;
    public float previewInterval = 1.2f;

    [Header("Lifecycle")]
    public bool destroyWhenDone = false;
    public UnityEvent onStruck;
    public UnityEvent onFinished;

    // ---- runtime ----
    Mesh mesh;
    MaterialPropertyBlock boltMpb, glowMpb;
    bool alive, impactFired;
    float age, regenTimer, flicker = 1f, previewTimer;
    float length;
    Vector3 localEnd, worldEnd, strikeDir = Vector3.forward;

    readonly List<Vector3> verts = new List<Vector3>(512);
    readonly List<Vector3> uvs = new List<Vector3>(512);
    readonly List<Vector3> tangents = new List<Vector3>(512);
    readonly List<Color32> cols = new List<Color32>(512);
    readonly List<int> tris = new List<int>(1536);
    readonly List<Vector3> mainPath = new List<Vector3>(80);
    readonly List<Vector3> branchPath = new List<Vector3>(40);
    readonly List<Vector3> tmpA = new List<Vector3>(80);
    readonly List<Vector3> tmpB = new List<Vector3>(80);
    Vector3 bMin, bMax;

    static readonly int RevealId = Shader.PropertyToID("_Reveal");
    static readonly int IntensityId = Shader.PropertyToID("_Intensity");
    static readonly int WidthId = Shader.PropertyToID("_Width");
    static readonly int WidthScaleId = Shader.PropertyToID("_WidthScale");

    void Awake()
    {
        EnsureInit();
        SetVisible(false);
    }

    void EnsureInit()
    {
        if (mesh != null) return;

        if (!boltMeshFilter || !boltRenderer)
        {
            Transform t = transform.Find("Bolt");
            if (t)
            {
                if (!boltMeshFilter) boltMeshFilter = t.GetComponent<MeshFilter>();
                if (!boltRenderer) boltRenderer = t.GetComponent<MeshRenderer>();
            }
        }

        mesh = new Mesh { name = "LightningBolt", hideFlags = HideFlags.HideAndDontSave };
        mesh.MarkDynamic();
        if (boltMeshFilter) boltMeshFilter.sharedMesh = mesh;

        boltMpb = new MaterialPropertyBlock();
        glowMpb = new MaterialPropertyBlock();
    }

    void OnEnable()
    {
        previewTimer = Mathf.Max(0f, previewInterval - 0.3f);
    }

    void OnDestroy()
    {
        if (mesh)
        {
            if (Application.isPlaying) Destroy(mesh);
            else DestroyImmediate(mesh);
        }
    }

    // ============================================================ API

    /// <summary>Strike from the current position toward a world point.</summary>
    public void Strike(Vector3 end) => Strike(transform.position, end);

    /// <summary>Fire the bolt between two world positions.</summary>
    public void Strike(Vector3 start, Vector3 end)
    {
        Vector3 d = end - start;
        length = d.magnitude;
        if (length < 0.05f) return;

        strikeDir = d / length;
        transform.SetPositionAndRotation(start, Quaternion.LookRotation(strikeDir));
        localEnd = new Vector3(0f, 0f, length);
        worldEnd = end;

        age = 0f;
        regenTimer = 0f;
        flicker = 1f;
        alive = true;
        impactFired = false;

        BuildMesh();
        SetVisible(true);
        if (impactGlow) impactGlow.enabled = false;
        ApplyVisual(0f, 1f, 1f);
    }

    /// <summary>Fire the bolt with a custom overall size (thickness, glow and sparks).</summary>
    public void Strike(Vector3 start, Vector3 end, float sizeMultiplier)
    {
        size = Mathf.Max(0.05f, sizeMultiplier);
        Strike(start, end);
    }

    /// <summary>Change the overall size at any time (also while the bolt is alive).</summary>
    public void SetSize(float sizeMultiplier)
    {
        size = Mathf.Max(0.05f, sizeMultiplier);
    }

    /// <summary>Cut the bolt short.</summary>
    public void Stop()
    {
        if (alive) Finish();
    }

    // ========================================================== update

    void Update()
    {
        Tick(Time.deltaTime);
    }

    void Tick(float dt)
    {
        if (!alive)
        {
            if (previewLoop && Application.isPlaying)
            {
                previewTimer += dt;
                if (previewTimer >= previewInterval)
                {
                    previewTimer = 0f;
                    Strike(transform.position, transform.position + transform.forward * previewLength);
                }
            }
            return;
        }

        age += dt;
        if (age >= lifetime)
        {
            Finish();
            return;
        }

        // re-roll the shape = lightning flicker
        regenTimer += dt;
        if (regenTimer >= 1f / Mathf.Max(1f, regenerateRate))
        {
            regenTimer = 0f;
            BuildMesh();
            flicker = Random.value < dropoutChance ? 0.35f : 1f + (Random.value * 2f - 1f) * flickerAmount;
        }

        float reveal = revealTime <= 0f ? 1f : Mathf.Clamp01(age / revealTime);

        // the end of the bolt has been reached -> impact
        if (!impactFired && reveal >= 1f)
        {
            impactFired = true;
            if (impactGlow) impactGlow.enabled = true;
            if (sparks)
            {
                sparks.transform.SetPositionAndRotation(worldEnd, Quaternion.LookRotation(-strikeDir));
                if (Application.isPlaying) sparks.Play(true);   // in edit mode the preview drives the sparks
            }
            if (Application.isPlaying) onStruck?.Invoke();
        }

        float fadeStart = lifetime * 0.4f;
        float fade = age < fadeStart ? 1f : 1f - Mathf.InverseLerp(fadeStart, lifetime, age);
        fade *= fade;

        ApplyVisual(reveal, fade * flicker, Mathf.Lerp(0.45f, 1f, fade));
    }

    void Finish()
    {
        alive = false;
        SetVisible(false);
        if (Application.isPlaying)
        {
            onFinished?.Invoke();
            if (destroyWhenDone && !previewLoop) Destroy(gameObject);
        }
    }

    void SetVisible(bool v)
    {
        if (boltRenderer) boltRenderer.enabled = v;
        if (impactGlow && !v) impactGlow.enabled = false;
    }

    void ApplyVisual(float reveal, float intensity, float widthScale)
    {
        if (boltRenderer)
        {
            boltRenderer.GetPropertyBlock(boltMpb);
            boltMpb.SetFloat(RevealId, reveal);
            boltMpb.SetFloat(IntensityId, 1.4f * intensity);
            boltMpb.SetFloat(WidthId, width * size);
            boltMpb.SetFloat(WidthScaleId, widthScale);
            boltRenderer.SetPropertyBlock(boltMpb);
        }

        if (impactGlow)
        {
            impactGlow.transform.position = worldEnd;
            impactGlow.transform.localScale = Vector3.one * (impactGlowSize * size * (0.6f + 0.4f * flicker) * widthScale);
            impactGlow.GetPropertyBlock(glowMpb);
            glowMpb.SetFloat(IntensityId, 1.4f * intensity);
            impactGlow.SetPropertyBlock(glowMpb);
        }

        if (sparks) sparks.transform.localScale = Vector3.one * (size * sparkSize);
    }

    // ===================================================== mesh build

    void BuildMesh()
    {
        verts.Clear(); uvs.Clear(); tangents.Clear(); cols.Clear(); tris.Clear();
        bMin = new Vector3(float.MaxValue, float.MaxValue, float.MaxValue);
        bMax = new Vector3(float.MinValue, float.MinValue, float.MinValue);

        // main bolt
        GeneratePath(Vector3.zero, localEnd, detail, jaggedness * length, mainPath);
        AddRibbon(mainPath, 0f, 1f, false);

        // branches
        int n = mainPath.Count;
        for (int b = 0; b < branchCount && n > 6; b++)
        {
            int idx = Mathf.Clamp(Random.Range(Mathf.RoundToInt(n * 0.15f), Mathf.RoundToInt(n * 0.8f)), 1, n - 2);
            Vector3 origin = mainPath[idx];
            Vector3 mainDir = (mainPath[idx + 1] - mainPath[idx - 1]).normalized;

            float angle = Random.Range(branchAngle.x, branchAngle.y);
            Vector3 axis = RandomPerp(mainDir);
            Vector3 bdir = (Quaternion.AngleAxis(angle, axis) * mainDir + mainDir * 0.4f).normalized;

            float blen = length * Random.Range(branchLength.x, branchLength.y);
            GeneratePath(origin, origin + bdir * blen, Mathf.Max(2, detail - 2), jaggedness * blen, branchPath);
            AddRibbon(branchPath, idx / (float)(n - 1), 0.08f, true);
        }

        mesh.Clear();
        mesh.SetVertices(verts);
        mesh.SetUVs(0, uvs);
        mesh.SetNormals(tangents);
        mesh.SetColors(cols);
        mesh.SetTriangles(tris, 0);

        // padded bounds (the shader widens the ribbon, and branches wander)
        Vector3 pad = Vector3.one * (width * size * 2f + 0.5f);
        Bounds bounds = new Bounds();
        bounds.SetMinMax(bMin - pad, bMax + pad);
        mesh.bounds = bounds;
    }

    void AddRibbon(List<Vector3> path, float revealBase, float revealSpan, bool isBranch)
    {
        int count = path.Count;
        if (count < 2) return;
        int baseIdx = verts.Count;

        for (int i = 0; i < count; i++)
        {
            float p = i / (float)(count - 1);
            Vector3 tan = i == 0 ? path[1] - path[0]
                        : i == count - 1 ? path[i] - path[i - 1]
                        : path[i + 1] - path[i - 1];
            tan = tan.sqrMagnitude > 1e-8f ? tan.normalized : Vector3.forward;

            float reveal = isBranch ? revealBase + p * revealSpan : p;
            float widthMul = isBranch ? branchWidth * Mathf.Pow(1f - p, 0.7f) : Mathf.Lerp(1f, 0.65f, p);
            float inten = isBranch ? branchIntensity * (1f - p * 0.5f) : 1f;
            Color32 c = new Color32((byte)(Mathf.Clamp01(widthMul) * 255f), (byte)(Mathf.Clamp01(inten) * 255f),
                                    (byte)(isBranch ? 255 : 0), 255);

            Vector3 pt = path[i];
            verts.Add(pt); verts.Add(pt);
            uvs.Add(new Vector3(reveal, 0f, p)); uvs.Add(new Vector3(reveal, 1f, p));
            tangents.Add(tan); tangents.Add(tan);
            cols.Add(c); cols.Add(c);

            bMin = Vector3.Min(bMin, pt);
            bMax = Vector3.Max(bMax, pt);
        }

        for (int i = 0; i < count - 1; i++)
        {
            int a = baseIdx + i * 2;
            tris.Add(a); tris.Add(a + 1); tris.Add(a + 2);
            tris.Add(a + 1); tris.Add(a + 3); tris.Add(a + 2);
        }
    }

    // midpoint displacement: split every segment, push the new midpoint sideways, halve the push each round
    void GeneratePath(Vector3 a, Vector3 b, int iterations, float amp, List<Vector3> result)
    {
        tmpA.Clear();
        tmpA.Add(a);
        tmpA.Add(b);
        List<Vector3> src = tmpA, dst = tmpB;

        for (int it = 0; it < iterations; it++)
        {
            dst.Clear();
            for (int i = 0; i < src.Count - 1; i++)
            {
                Vector3 p0 = src[i], p1 = src[i + 1];
                Vector3 d = p1 - p0;
                float l = d.magnitude;
                Vector3 mid = (p0 + p1) * 0.5f;
                if (l > 1e-5f) mid += RandomPerp(d / l) * (Random.Range(-1f, 1f) * amp);
                dst.Add(p0);
                dst.Add(mid);
            }
            dst.Add(src[src.Count - 1]);

            List<Vector3> swap = src; src = dst; dst = swap;
            amp *= 0.55f;
        }

        result.Clear();
        result.AddRange(src);
    }

    static Vector3 RandomPerp(Vector3 dir)
    {
        Vector3 p = Vector3.Cross(dir, Random.onUnitSphere);
        if (p.sqrMagnitude < 1e-6f) p = Vector3.Cross(dir, Vector3.up);
        return p.normalized;
    }

#if UNITY_EDITOR
    // ------------- Edit-mode preview (driven by LightningBoltEditor, no Play mode needed) -------------
    bool edActive, edSparksRunning, edPrevAutoSeed;
    float edTimer, edSparkTime;
    uint edPrevSeed;
    Vector3 edPos, edGlowPos, edGlowScale, edSparkPos, edSparkScale;
    Quaternion edRot, edSparkRot;

    public bool EditorPreviewActive => edActive;

    public void EditorPreviewStart()
    {
        EnsureInit();
        edActive = true;
        edPos = transform.position;
        edRot = transform.rotation;
        if (impactGlow)
        {
            edGlowPos = impactGlow.transform.position;
            edGlowScale = impactGlow.transform.localScale;
        }
        if (sparks)
        {
            edSparkPos = sparks.transform.position;
            edSparkRot = sparks.transform.rotation;
            edSparkScale = sparks.transform.localScale;
            edPrevAutoSeed = sparks.useAutoRandomSeed;
            edPrevSeed = sparks.randomSeed;
            sparks.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
            sparks.useAutoRandomSeed = false;
            sparks.randomSeed = 4242;
        }
        if (boltMeshFilter) boltMeshFilter.sharedMesh = mesh;
        edTimer = 0f;
        EditorStrikeNow();
    }

    public void EditorPreviewStop()
    {
        if (!edActive) return;
        edActive = false;
        alive = false;

        SetVisible(false);
        if (boltMeshFilter) boltMeshFilter.sharedMesh = null;     // never leave the temporary mesh in the scene
        if (boltRenderer) boltRenderer.SetPropertyBlock(null);

        transform.SetPositionAndRotation(edPos, edRot);
        if (impactGlow)
        {
            impactGlow.transform.position = edGlowPos;
            impactGlow.transform.localScale = edGlowScale;
            impactGlow.SetPropertyBlock(null);
        }
        if (sparks)
        {
            sparks.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
            sparks.transform.SetPositionAndRotation(edSparkPos, edSparkRot);
            sparks.transform.localScale = edSparkScale;
            sparks.useAutoRandomSeed = edPrevAutoSeed;
            if (!edPrevAutoSeed) sparks.randomSeed = edPrevSeed;
        }
    }

    public void EditorPreviewUpdate(float dt)
    {
        if (!edActive) return;

        if (!alive)
        {
            edTimer += dt;
            if (edTimer >= previewInterval)
            {
                edTimer = 0f;
                EditorStrikeNow();
            }
        }
        else
        {
            Tick(dt);
        }

        // particle systems do not run on their own in edit mode -> simulate the sparks by hand
        if (sparks)
        {
            if (impactFired && !edSparksRunning)
            {
                edSparksRunning = true;
                edSparkTime = 0f;
                sparks.transform.SetPositionAndRotation(worldEnd, Quaternion.LookRotation(-strikeDir));
            }
            if (edSparksRunning)
            {
                edSparkTime += dt;
                sparks.Simulate(edSparkTime, true, true);
                if (edSparkTime > 1.2f) edSparksRunning = false;
            }
        }
    }

    void EditorStrikeNow()
    {
        edSparksRunning = false;
        edSparkTime = 0f;
        if (sparks) sparks.Clear(true);
        Strike(edPos, edPos + (edRot * Vector3.forward) * previewLength);
    }
#endif

    [ContextMenu("Test Strike Forward")]
    void TestStrike() => Strike(transform.position, transform.position + transform.forward * previewLength);
}